from pathlib import Path
import base64, gzip, re, runpy
runpy.run_path("tools/patch_v065.py", run_name="__main__")
root=Path("WakeGuard")
java_dir=root/"app/src/main/java/jp/wakeguard/alarm"
main_path=java_dir/"MainActivity.java"
manifest_path=root/"app/src/main/AndroidManifest.xml"
build_path=root/"app/build.gradle.kts"
def dec(s): return gzip.decompress(base64.b64decode(s)).decode("utf-8")
CLOCK_B64=''
TIMER_B64=''
java_dir.mkdir(parents=True, exist_ok=True)
(java_dir/"ClockActivity.java").write_text(dec(CLOCK_B64), encoding="utf-8")
(java_dir/"TimerReceiver.java").write_text(dec(TIMER_B64), encoding="utf-8")
main=main_path.read_text(encoding="utf-8")
anchor='        TextView sub = new TextView(this);\n        sub.setText("完全無料・広告なし・通信なし。歩数ミッション完了まで時間では自動停止しません。");\n        sub.setTextSize(15); root.addView(sub);\n\n'
addition='        Button clockTools = new Button(this);\n        clockTools.setText("🕒 世界時計・ストップウォッチ・タイマー");\n        clockTools.setAllCaps(false);\n        clockTools.setOnClickListener(v -> startActivity(new Intent(this, ClockActivity.class)));\n        LinearLayout.LayoutParams ctp = new LinearLayout.LayoutParams(-1, -2);\n        ctp.setMargins(0, 16, 0, 12);\n        root.addView(clockTools, ctp);\n\n'
if anchor not in main: raise SystemExit("v070: MainActivity header anchor not found")
main_path.write_text(main.replace(anchor,anchor+addition,1),encoding="utf-8")
manifest=manifest_path.read_text(encoding="utf-8")
a='        <activity\n            android:name=".MainActivity"\n            android:exported="true">\n'
if a not in manifest: raise SystemExit("v070: manifest MainActivity anchor not found")
manifest=manifest.replace(a,'        <activity\n            android:name=".ClockActivity"\n            android:exported="false" />\n\n'.replace('\\n','\n')+a,1)
r='        <receiver android:name=".AlarmReceiver" android:exported="false" />\n'
if r not in manifest: raise SystemExit("v070: manifest receiver anchor not found")
manifest=manifest.replace(r,r+'        <receiver android:name=".TimerReceiver" android:exported="false" />\n',1)
manifest_path.write_text(manifest,encoding="utf-8")
build=build_path.read_text(encoding="utf-8")
build,n1=re.subn(r"versionCode\s*=\s*\d+","versionCode = 21",build,count=1)
build,n2=re.subn(r'versionName\s*=\s*"[^"]+"','versionName = "0.7.0"',build,count=1)
if n1!=1 or n2!=1: raise SystemExit("v070: version bump failed")
build_path.write_text(build,encoding="utf-8")
print("Applied WakeGuard v0.7.0 full clock suite")
